"""Browser test of selling ZP for bitcoin from the wallet's Markets screen: own offers, a new offer, taking one back.
Setup:  node build.mjs && (cd dist && python3 -m http.server 8081 &) && node tools/ui-test/mock-node.mjs --port 8082 &
        python3 tools/ui-test/run-swap.py [--out DIR]
The wallet's node is http://localhost:8082/node, so the wallet reads the site's /swap/status next to it (the mock serves it)."""
import sys, json, urllib.request, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', '..', 'node_modules'))
from playwright.sync_api import sync_playwright
OUT = sys.argv[sys.argv.index('--out') + 1] if '--out' in sys.argv else '/tmp/claude-0/ui'
os.makedirs(OUT, exist_ok=True)
APP, NODE = 'http://localhost:8081/index.html', 'http://localhost:8082'
PHRASE = ' '.join(['abandon'] * 23 + ['art'])
bad = []
def ok(c, m):
    print(('OK   ' if c else 'FAIL ') + m)
    if not c: bad.append(m)
def mock(**kw): urllib.request.urlopen(NODE + '/__set?' + '&'.join(f'{k}={v}' for k, v in kw.items())).read()
def published(): return json.load(urllib.request.urlopen(NODE + '/__published'))
with sync_playwright() as p:
    b = p.chromium.launch(); ctx = b.new_context(viewport={'width': 390, 'height': 860})
    ctx.add_init_script("localStorage.setItem('zp-wallet.settings.v1', JSON.stringify({network:'test', nodes:{test:'%s/node', main:'%s/node'}, stab:'sell'}))" % (NODE, NODE))
    # Bitcoin as mempool.space answers: one address has received bitcoin before, the others never did
    FUNDED = 'bc1qar0srrr7xfkvy5l643lydnw9re59gtzzwf5mdq'
    ctx.route('https://mempool.space/**', lambda r: r.fulfill(status=200, content_type='application/json', headers={'Access-Control-Allow-Origin': '*'},
        body=json.dumps({'chain_stats': {'funded_txo_count': 2 if r.request.url.endswith(FUNDED) else 0}, 'mempool_stats': {'funded_txo_count': 0}})))
    pg = ctx.new_page(); errors = []
    pg.on('pageerror', lambda e: errors.append('pageerror: ' + str(e)))
    mock(tip=2100, zp=10, utxo=0, reset=1)
    pg.goto(APP); pg.wait_for_selector('form[data-form=create-vault]')
    pg.fill('input[name=p1]', 'password123'); pg.fill('input[name=p2]', 'password123'); pg.click('form[data-form=create-vault] button.primary')
    pg.wait_for_selector('form[data-form=add-wallet]'); pg.click('button[data-tab=phrase]'); pg.fill('textarea[name=words]', PHRASE); pg.click('form[data-form=add-wallet] button.primary')
    pg.wait_for_selector('[data-go=markets]'); pg.wait_for_timeout(800)
    pg.click('nav >> text=Markets'); pg.wait_for_selector('[data-mtab=oracle][aria-selected=true]'); pg.wait_for_timeout(800)
    ok('BTC' in pg.inner_text('main') and pg.query_selector('.book') is None, 'Markets opens on the Oracle tab, prices only')
    pg.screenshot(path=f'{OUT}/m1-oracle.png', full_page=True)
    pg.click('[data-mtab=dex]'); pg.wait_for_timeout(300); ok(pg.query_selector('.book') is not None and 'Spread' in pg.inner_text('.book'), 'Dex tab shows the order book')
    pg.screenshot(path=f'{OUT}/m2-dex.png', full_page=True)
    pg.click('[data-mtab=swap]'); pg.wait_for_selector('h2:has-text("Your sell offers")'); pg.wait_for_timeout(300)
    card = pg.inner_text('.card:has(h2:has-text("Your sell offers"))')
    ok('YOU SELL\n3 ZP\nYOU RECEIVE\n0.00060000 BTC' in card and '1 ZP' in card and '0.00020000 BTC' in card, 'own offers listed from the seller\'s side: You sell / You receive')
    ok('0.00020000 BTC per ZP' in card and '≈ $20.00' in card, 'each offer shows its price per ZP, in dollars from the oracle\'s BTC price')
    ok('7 ZP' not in card, 'another seller\'s offer is not listed as mine')
    ok('a late payment can still arrive until then' in card and pg.query_selector('button[data-act=swap-cancel][data-id=o-mine3][disabled]') is not None, 'Take back disabled, with the reason, in the 10 blocks after a reservation ended')
    ok(pg.query_selector('button[data-act=swap-cancel][data-id=o-mine1]:not([disabled])') is not None and pg.query_selector('button[data-act=swap-cancel][data-id=o-mine2][disabled]') is not None and 'if the buyer does not pay, you can take it back' in card, 'Take back on the open offer; on the reserved one disabled with the reason')
    ok('Reserved by a buyer' in card and 'The buyer pays you' in card, 'a reserved offer shows the steps of the sale')
    pg.screenshot(path=f'{OUT}/s1-markets.png', full_page=True)
    # new offer
    pg.click('button[data-act=swap-new]'); pg.wait_for_selector('form[data-form=offer]')
    ok(pg.query_selector('button[data-act=price-mode][data-v=usd].on') is not None and pg.query_selector('input[name=per]') is not None, 'the offer opens in $ per ZP when the oracle has a Bitcoin price')
    pg.click('button[data-act=price-mode][data-v=total]')
    pg.fill('input[name=btc]', '0.0008'); pg.fill('input[name=zp]', '100'); pg.wait_for_timeout(150)
    ok('More than you have' in pg.inner_text('#offer-rate'), 'more ZP than the wallet has: said at once, as you type')
    pg.click('button[data-act=offer-max]'); pg.wait_for_timeout(150)
    ok(pg.input_value('input[name=zp]') == '9.99999999', 'Max fills the spendable ZP less the 1-kalapa fee (' + pg.input_value('input[name=zp]') + ')')
    pg.fill('input[name=zp]', '4'); pg.fill('input[name=btc]', '0.0008')
    ok('0.00020000 BTC per ZP (20,000 sat)' in pg.inner_text('#offer-rate'), 'rate shown: ' + pg.inner_text('#offer-rate'))
    pg.click('button[data-act=price-mode][data-v=usd]'); pg.fill('input[name=per]', '1')
    ok('Total 0.00004000 BTC' in pg.inner_text('#offer-rate') and pg.input_value('input[name=zp]') == '4', '$1 per ZP at $100,000 per BTC: 4 ZP = 0.00004 BTC (' + pg.inner_text('#offer-rate') + ')')
    pg.click('button[data-act=price-mode][data-v=sat]'); pg.fill('input[name=per]', '20000')
    ok('Total 0.00080000 BTC' in pg.inner_text('#offer-rate'), '20,000 sat per ZP: 4 ZP = 0.0008 BTC')
    pg.screenshot(path=f'{OUT}/s1b-offer-per-zp.png')
    ok(pg.query_selector('button[data-act=addr-src][data-v=key].on') is not None and pg.query_selector('input[name=xpub]') is not None, 'the Bitcoin addresses come from the account key by default')
    pg.click('button[data-act=addr-src][data-v=type]'); ok(pg.input_value('input[name=per]') == '20000', 'switching the address source keeps the price')
    pg.fill('textarea[name=addrs]', 'tb1qw508d6qejxtdg4y5r3zarvary0c5xw7kxpjzsx'); pg.click('form[data-form=offer] button.primary'); pg.wait_for_timeout(500)
    ok('testnet address' in pg.inner_text('.sheet'), 'a Bitcoin testnet address is refused (the contract follows mainnet)')
    pg.fill('textarea[name=addrs]', FUNDED); pg.click('form[data-form=offer] button.primary'); pg.wait_for_timeout(800)
    ok('already received bitcoin' in pg.inner_text('.sheet'), 'an address that already received bitcoin is refused')
    pg.fill('textarea[name=addrs]', 'bc1qrp33g0q5c5txsp9arysrx4k6zdkfs4nce4xj0gdcccefvpysxf3qccfmv3'); pg.click('form[data-form=offer] button.primary'); pg.wait_for_timeout(800)
    ok('is used by an offer in the market' in pg.inner_text('.sheet'), 'an address another offer uses is refused')
    ok(pg.query_selector('.sheet .err b') is not None and pg.query_selector('textarea[name=addrs][aria-invalid=true]') is not None, 'the error is a bold box, and the address field is marked')
    pg.screenshot(path=f'{OUT}/s1c-error.png')
    ok('Each line must be a new address' in pg.inner_text('.sheet'), 'the form explains: a new address per line, not a fixed one')
    pg.fill('textarea[name=addrs]', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4\n1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa'); pg.click('form[data-form=offer] button.primary')
    pg.wait_for_selector('button[data-act=confirm-offer]'); t = pg.inner_text('.sheet')
    ok('4 ZP' in t and '0.00080000 BTC' in t and 'Bitcoin address 2' in t, 'confirm shows amount, price and both addresses')
    pg.screenshot(path=f'{OUT}/s2-confirm-offer.png')
    pg.click('button[data-act=confirm-offer]'); pg.wait_for_selector('h2:has-text("Broadcast successfully")')
    pub = published(); ok(len(pub) == 1, 'one transaction published')
    ok(len(pg.evaluate("JSON.parse(localStorage.getItem('zp-wallet.btc-scripts.v1'))")) == 2, 'the two addresses are remembered')
    pg.click('button[data-act=close]'); pg.wait_for_timeout(300)
    card = pg.inner_text('.card:has(h2:has-text("Your sell offers"))')
    ok('4 ZP' in card and '0.00080000 BTC' in card and 'waiting for the next block' in card, 'the sent offer shows at once, waiting for its block')
    pg.screenshot(path=f'{OUT}/s2b-waiting.png')
    # check the published transaction with the wallet's own reader (node), outside the browser
    import subprocess
    chk = subprocess.run(['node', '-e', '''
      import('./src/serialize.js').then(({ deserializeTx, unhex, hex }) => {
        const tx = deserializeTx(unhex(process.argv[1]));
        const c = tx.witnesses.find(w => w.type === 'Contract'), out = tx.outputs.find(o => o.lock.type === 'Contract' && o.spend.asset.contract.version === 0);
        console.log(JSON.stringify({ cmd: c.command, signed: !!c.signature, locked: String(out.spend.amount), pk: tx.witnesses.filter(w => w.type === 'PK').length }));
      });''', pub[0]], capture_output=True, text=True, cwd=os.path.join(os.path.dirname(__file__), '..', '..'))
    info = json.loads(chk.stdout or '{}'); print('   ', info)
    ok(info.get('cmd') == 'offer' and info.get('signed') and info.get('locked') == '400000000', 'the offer transaction locks 4 ZP and carries the seller\'s signature')
    # take back
    pg.click('button[data-act=swap-cancel][data-id=o-mine1]'); pg.wait_for_timeout(1200)
    ok('still waiting for its block' in pg.inner_text('main'), 'the output spent by the offer is not used again before its block')
    mock(utxo=1)   # the offer is in a block: the wallet has a new output
    pg.click('button[data-act=swap-cancel][data-id=o-mine1]'); pg.wait_for_selector('button[data-act=confirm-cancel]')
    ok('3 ZP for 0.00060000 BTC' in pg.inner_text('.sheet'), 'take back confirm names the offer')
    pg.screenshot(path=f'{OUT}/s3-confirm-cancel.png')
    pg.evaluate("localStorage.setItem('zp-wallet.btc-scripts.v1', JSON.stringify([...JSON.parse(localStorage.getItem('zp-wallet.btc-scripts.v1')), '0014' + '11'.repeat(20), '0014' + '22'.repeat(20)]))")
    pg.click('button[data-act=confirm-cancel]'); pg.wait_for_selector('h2:has-text("Broadcast successfully")')
    used = pg.evaluate("JSON.parse(localStorage.getItem('zp-wallet.btc-scripts.v1'))"); ok(len(used) == 2 and '0014' + '11' * 20 not in used, 'taking back an offer nobody reserved gives its Bitcoin addresses back (the gap limit)')
    ok(len(published()) == 2, 'cancel published')
    pg.click('button[data-act=close]')
    pg.click('button[data-act=swap-new]'); pg.wait_for_selector('form[data-form=offer]'); pg.fill('input[name=zp]', '1'); pg.fill('input[name=per]', '1')
    pg.click('button[data-act=addr-src][data-v=type]'); pg.fill('textarea[name=addrs]', 'bc1qw508d6qejxtdg4y5r3zarvary0c5xw7kv8f3t4'); pg.click('form[data-form=offer] button.primary'); pg.wait_for_timeout(800)
    ok('was used in an earlier offer' in pg.inner_text('.sheet'), 'an address from an earlier offer of this wallet is refused')
    pg.click('form[data-form=offer] button[data-act=close]')
    pg.click('nav >> text=Wallet'); pg.wait_for_timeout(300); pg.click('nav >> text=Markets'); pg.wait_for_timeout(600)
    ok(pg.query_selector('[data-mtab=swap][aria-selected=true]') is not None, 'the chosen Markets tab is kept when coming back')
    card = pg.inner_text('.card:has(h2:has-text("Your sell offers"))')
    ok('Taking back: waits for its block' in card and pg.query_selector('button[data-act=swap-cancel][data-id=o-mine1]') is None, 'after Take back: "Taking back" and no second Take back button')
    pg.screenshot(path=f'{OUT}/s4-taking-back.png')
    ok(pg.evaluate("JSON.parse(localStorage.getItem('zp-wallet.settings.v1')).mtab") == 'swap', 'and saved for the next visit')
    pg.click('nav >> text=Contracts'); pg.wait_for_timeout(500); ok('Create a contract' in pg.inner_text('main'), 'Contracts has a place for creating contracts (V1 engine)')
    pg.screenshot(path=f'{OUT}/c1-contracts.png', full_page=True)
    pg.reload(); pg.wait_for_selector('form[data-form=unlock]'); pg.fill('input[name=p]', 'password123'); pg.click('form[data-form=unlock] button.primary')
    pg.wait_for_selector('[data-go=contracts]'); pg.click('nav >> text=Markets'); pg.click('[data-mtab=swap]'); pg.wait_for_timeout(1500)
    ok('waiting for the next block' in pg.inner_text('main'), 'and still after a reload')
    # ZP in many small pieces: the offer is refused with a way out (combine them by one transfer to yourself)
    mock(split=1200); pg.click('nav >> text=Wallet'); pg.wait_for_timeout(500); pg.click('nav >> text=Markets'); pg.wait_for_timeout(800)
    pg.click('button[data-act=swap-new]'); pg.wait_for_selector('form[data-form=offer]')
    pg.fill('input[name=zp]', '9.9'); pg.click('button[data-act=price-mode][data-v=total]'); pg.fill('input[name=btc]', '0.0005')
    pg.click('button[data-act=addr-src][data-v=type]'); pg.fill('textarea[name=addrs]', 'bc1qcr8te4kr609gcawutmrza0j4xv80jy8z306fyu'); pg.click('form[data-form=offer] button.primary'); pg.wait_for_selector('.sheet .err', timeout=15000)
    ok('too many small pieces' in pg.inner_text('.sheet') and pg.query_selector('.sheet button[data-act=combine]') is not None, 'many small outputs: the reason and a "Combine my ZP now" button')
    pub0 = len(published()); pg.click('.sheet button[data-act=combine]'); pg.wait_for_selector('button[data-act=combine-send]', timeout=15000)
    t = pg.inner_text('.sheet'); ok('1,200' in t and '3 to your own address' in t and 'None' in t, 'Combine: 1,200 pieces in 3 transfers of up to 500 to your own address, no fee')
    pg.screenshot(path=f'{OUT}/s5-combine.png')
    pg.click('button[data-act=combine-send]'); pg.wait_for_selector('text=gather 1,200 pieces', timeout=30000)
    ok(len(published()) - pub0 == 3, 'three transfers published (%d)' % (len(published()) - pub0)); pg.click('button[data-act=close]')
    mock(split=0)
    ok(pg.evaluate('document.documentElement.scrollWidth <= innerWidth'), 'no horizontal scroll at 390px')
    ok(not errors, 'no page errors ' + '; '.join(errors))
    b.close()
print('ALL PASS' if not bad else f'FAILED {len(bad)}'); sys.exit(1 if bad else 0)
